`timescale 1ns / 1ps
// Repro for bucket B1 (data_byte): the eight data bits must leave least
// significant bit first. Only the data bits are checked.
module tb_uart_frame_tx;
    localparam integer C = 4;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    integer checks = 0;
    integer failed = 0;
    integer pos    = 0;
    reg     done   = 1'b0;
    reg [8*64-1:0] nonce;

    uart_frame_tx #(.CLKS_PER_BIT(C)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    task finish_run;
        begin
            if (!done) begin
                done = 1'b1;
                $display("VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks, failed);
                $finish;
            end
        end
    endtask

    // Advance to the negedge that follows posedge number `target` of the frame.
    task goto(input integer target);
        begin
            while (pos < target) begin
                @(negedge clk);
                pos = pos + 1;
            end
        end
    endtask

    task send_frame(input [7:0] d);
        begin
            @(negedge clk);
            data  = d;
            start = 1'b1;
            @(negedge clk);          // posedge 0 accepted the frame
            start = 1'b0;
            pos   = 0;
        end
    endtask

    task wait_idle;
        integer guard;
        begin
            guard = 0;
            while (busy && guard < 40 * C) begin
                @(negedge clk);
                guard = guard + 1;
            end
            repeat (2 * C) @(negedge clk);
        end
    endtask

    task check_data(input [7:0] d);
        integer i;
        begin
            send_frame(d);
            for (i = 0; i < 8; i = i + 1) begin
                goto((1 + i) * C + C / 2);
                checks = checks + 1;
                if (tx !== d[i]) begin
                    failed = failed + 1;
                    $display("CHECK FAIL data_lsb_first: byte %h bit %0d expected %b got %b",
                             d, i, d[i], tx);
                end
            end
            wait_idle;
        end
    endtask

    initial begin
        if (!$value$plusargs("nonce=%s", nonce)) nonce = "none";
        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);
        check_data(8'h01);
        check_data(8'hC5);
        check_data(8'h3A);
        finish_run;
    end

    initial begin
        #100000;
        failed = failed + 1;
        $display("CHECK FAIL watchdog: simulation did not complete");
        finish_run;
    end
endmodule
=== END FILE ===
